// Doctor dashboard: today's appointments, pending approvals, open cases, family requests.
import { useCallback, useEffect, useState } from 'react'
import { Link } from 'react-router-dom'

import { EmptyState, ErrorState, LoadingState } from '../../components/shared/ViewState'
import { threePortalApi, type DoctorDashboardSummaryDto, type DoctorRequestDto } from '../../services/apiClient'
import { extractErrorMessage, formatDateTime } from '../family/threePortalShared'

export function DoctorDashboardPanel() {
  const [data, setData] = useState<DoctorDashboardSummaryDto | null>(null)
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading')
  const [message, setMessage] = useState('')

  const load = useCallback(async () => {
    setStatus('loading')
    try {
      const { data: dashboard } = await threePortalApi.getDoctorDashboard()
      setData(dashboard)
      setStatus('ready')
    } catch {
      setStatus('error')
    }
  }, [])

  useEffect(() => {
    void load()
  }, [load])

  async function respond(request: DoctorRequestDto, accept: boolean) {
    try {
      if (accept) await threePortalApi.acceptFamilyDoctorRequest(request.id)
      else await threePortalApi.declineFamilyDoctorRequest(request.id)
      setMessage(accept ? `Accepted request from ${request.familyName}.` : `Declined request from ${request.familyName}.`)
      await load()
    } catch (error) {
      setMessage(extractErrorMessage(error, 'Request could not be updated.'))
    }
  }

  if (status === 'loading') return <LoadingState label="Loading your dashboard" />
  if (status === 'error') return <ErrorState message="Dashboard summary could not be loaded." onRetry={() => void load()} />
  if (!data) return <EmptyState title="No dashboard data" message="Nothing to show yet." />

  return (
    <div className="page-stack" aria-label="Doctor dashboard">
      {message && <p role="status" className="status-banner">{message}</p>}

      <section className="metric-grid" aria-label="Doctor metrics">
        <article className="metric-card metric-card--teal">
          <span>Today's appointments</span>
          <strong>{data.todayAppointments.length}</strong>
        </article>
        <article className="metric-card metric-card--amber">
          <span>Pending approvals</span>
          <strong>{data.pendingApprovals}</strong>
        </article>
        <article className="metric-card metric-card--blue">
          <span>Open cases</span>
          <strong>{data.openCases}</strong>
        </article>
        <article className="metric-card">
          <span>Assigned families</span>
          <strong>{data.assignedFamilies}</strong>
        </article>
      </section>

      <section className="panel">
        <div className="panel-heading">
          <h2>Today's appointments</h2>
          <Link className="button button--secondary" to="/doctor-calendar">Open calendar</Link>
        </div>
        {data.todayAppointments.length === 0 ? (
          <EmptyState title="No appointments today" message="Confirmed appointments for today will show here." />
        ) : (
          <ul className="activity-list">
            {data.todayAppointments.map((appointment) => (
              <li key={appointment.id}>
                <span>{appointment.memberDisplayName} · {appointment.familyName}</span>
                <small>{formatDateTime(appointment.startsAt)}</small>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section className="panel">
        <h2>Family doctor requests</h2>
        {data.pendingFamilyRequests.length === 0 ? (
          <EmptyState title="No pending requests" message="Families that request you as their doctor appear here." />
        ) : (
          <div className="table-scroll">
            <table>
              <thead>
                <tr>
                  <th>Family</th>
                  <th>Members</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {data.pendingFamilyRequests.map((request) => (
                  <tr key={request.id}>
                    <td>{request.familyName}</td>
                    <td>{request.memberCount}</td>
                    <td>
                      <button className="button button--primary" type="button" onClick={() => void respond(request, true)}>Accept</button>{' '}
                      <button className="button button--secondary" type="button" onClick={() => void respond(request, false)}>Decline</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </section>
    </div>
  )
}
